	LD	H,B
	LD	L,C
	EXX
	LD	H,B
	LD	L,C
	CALL	C,MATH_ADD1			;ROUND UP
	POP	BC			;RESTORE EXPONENT
	CALL	C,MATH_INCC
	RRA
	SBC	A,A
	ADD	A,C
	LD	C,A
	RES	7,H			;POSITIVE
	XOR	A
	RET
;
;TAN - Tangent function
;Result is floating-point numeric.
;
MATH_TAN:	CALL	MATH_SFLOAT
