	CALL	MATH_COS0
	CALL	MATH_POP5
	CALL	MATH_PUSH5
	CALL	MATH_SWAP
	CALL	MATH_SIN0
	CALL	MATH_POP5
	CALL	MATH_FDIV
	XOR	A			;NUMERIC MARKER
	RET
;
;COS - Cosine function
;Result is floating-point numeric.
;
MATH_COS:	CALL	MATH_SFLOAT
MATH_COS0:	CALL	MATH_SCALE
	INC	E
	INC	E
	LD	A,E
