	DEFW	0A8B7H			;a(8)
	DEFW	3611H
	DEFB	6DH
	DEFW	0DE26H			;a(6)
	DEFW	0D005H
	DEFB	73H
	DEFW	80C0H			;a(4)
	DEFW	888H
	DEFB	79H
	DEFW	0AA9DH			;a(2)
	DEFW	0AAAAH
	DEFB	7DH
	DEFW	0			;a(0)
	DEFW	0
	DEFB	80H
	CALL	MATH_POP5
	CALL	MATH_POP5
	CALL	MATH_FMUL
	JP	MATH_SIN3
;
MATH_SIN2:	CALL	MATH_SQUARE			;PUSH X*X
	CALL	MATH_POLY
	DEFW	0D571H			;b(8)
	DEFW	4C78H
	DEFB	70H
	DEFW	94AFH			;b(6)
	DEFW	0B603H
	DEFB	76H
	DEFW	9CC8H			;b(4)
	DEFW	2AAAH
	DEFB	7BH
	DEFW	0FFDDH			;b(2)
	DEFW	0FFFFH
	DEFB	7EH
	DEFW	0			;b(0)
	DEFW	0
	DEFB	80H
	CALL	MATH_POP5
MATH_SIN3:	POP	AF
	AND	4
	RET	Z
	DEC	C
	INC	C
	RET	Z			;ZERO
	SET	7,H			;MAKE NEGATIVE
	RET
;
;Floating-point one:
;
MATH_FONE:	LD	HL,0
	EXX
	LD	HL,0
	EXX
	LD	C,80H
	RET
;
MATH_DONE:	LD	DE,0
	EXX
	LD	DE,0
	EXX
	LD	B,80H
	RET
;
MATH_PIBY4:	LD	DE,490FH
	EXX
	LD	DE,0DAA2H
	EXX
	LD	B,7FH
	RET
;
;EXP - Exponential function
;Result is floating-point numeric.
;
MATH_EXP:	CALL	MATH_SFLOAT
MATH_EXP0:	CALL	MATH_LN2			;LN(2)
	EXX
	DEC	E
	LD	BC,0D1CFH		;0.6931471805599453
	EXX
	PUSH	HL			;H7=SIGN
	CALL	MATH_MOD48			;"MODULUS"
	POP	AF
	BIT	7,E
	JR	Z,MATH_EXP1
