	DEFW	4072H			;a(7)
	DEFW	942EH
	DEFB	73H
	DEFW	6F65H			;a(6)
	DEFW	2E4FH
	DEFB	76H
	DEFW	6D37H			;a(5)
	DEFW	8802H
	DEFB	79H
	DEFW	0E512H			;a(4)
	DEFW	2AA0H
	DEFB	7BH
	DEFW	4F14H			;a(3)
	DEFW	0AAAAH
	DEFB	7DH
	DEFW	0FD56H			;a(2)
	DEFW	7FFFH
	DEFB	7EH
	DEFW	0FFFEH			;a(1)
	DEFW	0FFFFH
	DEFB	7FH
	DEFW	0			;a(0)
	DEFW	0
	DEFB	80H
	CALL	MATH_POP5
	POP	AF
