	DEFW	74FBH
	DEFB	7DH
	DEFW	0AEAFH			;a(7)
	DEFW	11FFH
	DEFB	7EH
	DEFW	0D98CH			;a(5)
	DEFW	4CCDH
	DEFB	7EH
	DEFW	0A9E3H			;a(3)
	DEFW	2AAAH
	DEFB	7FH
	DEFW	0			;a(1)
	DEFW	0
	DEFB	81H
