;
;ATN - arc-tangent
;Result is floating-point numeric.
;
MATH_ATN:	CALL	MATH_SFLOAT
MATH_ATN0:	PUSH	HL			;SAVE SIGN
	RES	7,H
	LD	DE,5413H		;TAN(PI/8)=SQR(2)-1
