	DEFW	37D8H
	DEFB	7BH
	DEFW	6B91H			;a(11)
	DEFW	0AAB9H
	DEFB	7CH
	DEFW	41DEH			;a(9)
	DEFW	6197H
	DEFB	7CH
	DEFW	9D7BH			;a(7)
	DEFW	9237H
	DEFB	7DH
	DEFW	2A5AH			;a(5)
	DEFW	4CCCH
